package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import org.apache.commons.lang3.StringUtils;
import org.apache.commons.lang3.text.WordUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class StringUtils_indexOfAny_TriageGen2Test {

    private static final int INDEX_NOT_FOUND = -1;

    @Test
    public void testIndexOfAny_NullCharSequence() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny(null, new char[]{'a'}));
    }

    @Test
    public void testIndexOfAny_EmptyCharSequence() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny("", new char[]{'a'}));
    }

    @Test
    public void testIndexOfAny_NullSearchChars() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny("abc", null));
    }

    @Test
    public void testIndexOfAny_EmptySearchChars() {
        // Note: ArrayUtils.isEmpty(char[]) returns true for length 0
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny("abc", new char[]{}));
    }

    @Test
    public void testIndexOfAny_FoundAtStart() {
        assertEquals(0, StringUtils.indexOfAny("abc", new char[]{'a', 'b'}));
    }

    @Test
    public void testIndexOfAny_FoundInMiddle() {
        assertEquals(1, StringUtils.indexOfAny("abc", new char[]{'b'}));
    }

    @Test
    public void testIndexOfAny_FoundAtEnd() {
        assertEquals(2, StringUtils.indexOfAny("abc", new char[]{'c'}));
    }

    @Test
    public void testIndexOfAny_NotFound() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny("abc", new char[]{'z', 'y'}));
    }

    @Test
    public void testIndexOfAny_MultipleMatchesReturnsFirstOccurrence() {
        assertEquals(0, StringUtils.indexOfAny("banana", new char[]{'a', 'n'}));
    }

    /**
     * Tests the supplementary character logic (High Surrogate).
     * The code checks if searchChars[j+1] == cs.charAt(i+1) for high surrogates.
     */
    @Test
    public void testIndexOfAny_SupplementaryCharacter_Match() {
        // U+1F600 (Grinning Face) is represented by surrogate pair: \uD83D \uDE00
        String emoji = "\uD83D\uDE00";
        char[] search = new char[]{\uD83D, \uDE00};
        assertEquals(0, StringUtils.indexOfAny(emoji, search));
    }

    @Test
    public void testIndexOfAny_SupplementaryCharacter_PartialMatchFail() {
        // The char at i is a high surrogate, but the next char in cs doesn't match the next char in searchChars
        String emoji = "\uD83D\uDE00";
        char[] search = new char[]{\uD83D, \uDE01}; // different low surrogate
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny(emoji, search));
    }

    @Test
    public void testIndexOfAny_SupplementaryCharacter_BoundaryCondition() {
        // High surrogate at the very end of the string (should not trigger the inner surrogate check due to i < csLast)
        String edge = "\uD83D"; 
        char[] search = new char[]{\uD83D};
        assertEquals(0, StringUtils.indexOfAny(edge, search));
    }

    @Test
    public void testIndexOfAny_HighSurrogateIsLastInSearchChars() {
        // If the high surrogate is the last element in searchChars, j < searchLast will be false
        String emoji = "\uD83D\uDE00";
        char[] search = new char[]{\uD83D}; 
        // The loop j <= searchLen will run. When j=0, searchChars[0] == ch.
        // j < searchLast (0 < 0) is false. Returns i.
        assertEquals(0, StringUtils.indexOfAny(emoji, search));
    }

    @Test
    public void testIndexOfAny_HighSurrogateMatchButNotFullPair() {
        // cs has high surrogate at end
        String cs = "a\uD83D";
        char[] search = new char[]{\uD83D, \uDE00};
        // i=1, csLen=2, csLast=1. i < csLast is false.
        assertEquals(1, StringUtils.indexOfAny(cs, search));
    }
}
